$db->beginTransaction();try{$m=$members[0];$db->prepare('UPDATE members SET member_since=NULL WHERE id=?')->execute([$m['member_id']]);profileCheck($repo->find(new MemberProfileIdentifier((int)$m['member_id'],null))['member_since']===null,'unknown tenure stays null');$db->prepare('DELETE FROM person_relationships WHERE related_person_id=? AND relationship_type IN (\'payer\',\'self\')')->execute([$m['person_id']]);$empty=$service->profile(new MemberProfileIdentifier((int)$m['member_id'],null),'',false);profileCheck($empty['totals']===[]&&!$empty['exclusive'],'unlinked member has no invented financial totals');}finally{$db->rollBack();}
$db->beginTransaction();try{$m=$members[0];$payers=$repo->payers((int)$m['member_id']);if($payers){$payer=$payers[0]['payer_person_id'];$db->prepare("DELETE FROM person_relationships WHERE person_id=? AND related_person_id<>? AND relationship_type IN ('payer','self')")->execute([$payer,$m['person_id']]);$exclusive=$service->profile(new MemberProfileIdentifier((int)$m['member_id'],null),'usd',false);profileCheck($exclusive['exclusive']&&count($exclusive['totals'])===1,'exclusive payer allocation enables factual member totals');}}finally{$db->rollBack();}
